package com.example.prediksifasebulan.ui.result;
import android.graphics.*; import android.net.Uri; import android.os.Bundle; import android.content.res.ColorStateList;
import androidx.appcompat.app.AppCompatActivity; import androidx.lifecycle.ViewModelProvider; import androidx.core.content.ContextCompat;
import com.bumptech.glide.Glide; import com.example.prediksifasebulan.R; import com.example.prediksifasebulan.data.local.entity.WeatherData; import com.example.prediksifasebulan.databinding.ActivityResultBinding; import com.example.prediksifasebulan.domain.*;
import java.io.InputStream;
public class ResultActivity extends AppCompatActivity {
 public static final String EXTRA_IMAGE_URI="extra_image_uri"; private ActivityResultBinding binding; private ResultViewModel viewModel; private WeatherData displayedWeather;
 @Override protected void onCreate(Bundle state){super.onCreate(state);binding=ActivityResultBinding.inflate(getLayoutInflater());setContentView(binding.getRoot());viewModel=new ViewModelProvider(this).get(ResultViewModel.class);String raw=getIntent().getStringExtra(EXTRA_IMAGE_URI);if(raw==null){finish();return;}Uri uri=Uri.parse(raw);Glide.with(this).load(uri).into(binding.ivPreview);viewModel.getLatestWeather().observe(this,w->{showWeather(w);Bitmap b=bitmap(uri);if(b!=null)viewModel.classifyAndRecommend(b,w);});viewModel.getClassification().observe(this,r->{if(r!=null){binding.tvMoonPhase.setText(phase(r.getClassName()));binding.tvConfidence.setText(getString(R.string.confidence,r.getConfidence()*100));binding.tvMoonInfo.setText(info(r.getClassName()));}});viewModel.getRecommendation().observe(this,this::showRecommendation);}
 private Bitmap bitmap(Uri uri){try(InputStream in=getContentResolver().openInputStream(uri)){return BitmapFactory.decodeStream(in);}catch(Exception e){return null;}}
 private void showWeather(WeatherData w){displayedWeather=w;if(w==null){binding.tvWeatherSummary.setText(R.string.weather_unavailable_refresh);return;}binding.tvWeatherSummary.setText(getString(R.string.weather_summary,w.getWaveHeight(),w.getWindSpeed(),w.getVisibility()));binding.tvWaveValue.setText(getString(R.string.wave_value,w.getWaveHeight()));binding.tvWindValue.setText(getString(R.string.wind_value,w.getWindSpeed()));binding.tvVisibilityValue.setText(getString(R.string.visibility_value,w.getVisibility()));}
 private void showRecommendation(RecommendationResult r){if(r==null)return;binding.tvRecommendationTitle.setText(level(r.getRecommendationLevel()));binding.tvStatusBadge.setText(level(r.getRecommendationLevel()));int color=color(r.getRecommendationLevel());binding.tvStatusBadge.setBackgroundTintList(ColorStateList.valueOf(color));binding.viewStatusIndicator.setBackgroundColor(color);binding.tvRecommendationDesc.setText(description(r.getRecommendationLevel()));StringBuilder b=new StringBuilder();for(VetoReason x:r.getDangerReasons()){if(b.length()>0)b.append('\n');b.append(veto(x));}binding.tvDangerReasons.setText(b);}
 private int color(RecommendationLevel l){switch(l){case HIGHLY_RECOMMENDED:return ContextCompat.getColor(this,R.color.recommend_green);case RECOMMENDED:return ContextCompat.getColor(this,R.color.recommend_teal);case MODERATE:return ContextCompat.getColor(this,R.color.recommend_yellow);case NOT_RECOMMENDED:return ContextCompat.getColor(this,R.color.recommend_orange);default:return ContextCompat.getColor(this,R.color.recommend_red);}}
 private String level(RecommendationLevel l){switch(l){case HIGHLY_RECOMMENDED:return getString(R.string.status_highly_recommended);case RECOMMENDED:return getString(R.string.status_recommended);case MODERATE:return getString(R.string.status_moderate);case NOT_RECOMMENDED:return getString(R.string.status_not_recommended);default:return getString(R.string.status_dangerous);}}
 private String description(RecommendationLevel l){switch(l){case HIGHLY_RECOMMENDED:return getString(R.string.recommendation_highly);case RECOMMENDED:return getString(R.string.recommendation_recommended);case MODERATE:return getString(R.string.recommendation_moderate);case NOT_RECOMMENDED:return getString(R.string.recommendation_not_recommended);default:return getString(R.string.recommendation_dangerous);}}
 private String veto(VetoReason r){double value=displayedWeather==null?0d:(r==VetoReason.WIND_SPEED_EXCEEDED?displayedWeather.getWindSpeed():r==VetoReason.LOW_VISIBILITY?displayedWeather.getVisibility():displayedWeather.getWaveHeight());return getString(r==VetoReason.WIND_SPEED_EXCEEDED?R.string.veto_wind:r==VetoReason.LOW_VISIBILITY?R.string.veto_visibility:r==VetoReason.WAVE_RISK?R.string.warning_wave:r==VetoReason.WAVE_MODERATE_CEILING?R.string.wave_moderate_ceiling:R.string.veto_wave,value);}
 private String phase(String c){if(c.contains("New"))return getString(R.string.moon_phase_new_moon);if(c.contains("Full"))return getString(R.string.moon_phase_full_moon);if(c.contains("First"))return getString(R.string.moon_phase_first_quarter);if(c.contains("Third"))return getString(R.string.moon_phase_third_quarter);if(c.contains("Waxing_Gibbous"))return getString(R.string.moon_phase_waxing_gibbous);if(c.contains("Waning_Gibbous"))return getString(R.string.moon_phase_waning_gibbous);return c.contains("Waxing")?getString(R.string.moon_phase_waxing_crescent):getString(R.string.moon_phase_waning_crescent);}
 private String info(String c){return phase(c);}
}
